namespace TutorSphere.Application.Services;

public static partial class TeacherContractCatalog
{
    private static IReadOnlyList<TeacherContractSectionDef> SpanishSections() =>
    [
        new("parties", "Las partes",
            "### 1. El grupo o establecimiento\n\n**Nombre:** {{GROUP_NAME}}\n**Forma jurídica:** {{GROUP_LEGAL_FORM}}\n**Número de registro:** {{GROUP_REGISTRATION_NUMBER}}\n**Dirección:** {{GROUP_ADDRESS}}\n**Representado por:** {{GROUP_ADMIN_NAME}}\n**Función:** {{GROUP_ADMIN_ROLE}}\n\nEn lo sucesivo, «el Grupo».\n\n### 2. El docente\n\n**Nombre y apellidos:** {{TEACHER_FULL_NAME}}\n**Fecha de nacimiento:** {{TEACHER_DATE_OF_BIRTH}}\n**Dirección:** {{TEACHER_ADDRESS}}\n**País de residencia:** {{TEACHER_COUNTRY}}\n**Correo:** {{TEACHER_EMAIL}}\n**Teléfono:** {{TEACHER_PHONE}}\n**Materias impartidas:** {{TEACHER_SUBJECTS}}\n**Niveles escolares:** {{TEACHER_LEVELS}}\n\nEn lo sucesivo, «el Docente».\n\nEl Grupo y el Docente se denominan colectivamente «las Partes»."),
        new("preamble", "Preámbulo",
            "El Grupo utiliza la plataforma **TutorSphere** para organizar y prestar servicios de apoyo escolar, tutoría y acompañamiento pedagógico.\n\nEl Docente declara poseer las competencias, titulaciones y experiencia necesarias para prestar los servicios pedagógicos que se le encomienden.\n\nLas Partes desean definir, mediante el presente contrato, las condiciones de su colaboración."),
        new("art1", "Artículo 1 — Objeto",
            "El presente contrato tiene por objeto definir las condiciones en las que el Docente presta servicios de tutoría, apoyo escolar o acompañamiento pedagógico a los alumnos inscritos ante el Grupo en TutorSphere.\n\nLos servicios pueden incluir: la preparación e impartición de clases individuales o colectivas; la evaluación de las necesidades pedagógicas; la preparación de materiales; la creación, corrección y seguimiento de deberes; la redacción de informes de progreso; la comunicación con los padres o tutores legales; la participación en reuniones del Grupo; y cualquier otra actividad pedagógica acordada."),
        new("art2", "Artículo 2 — Estatuto del docente",
            "Salvo disposición legal en contrario, el Docente interviene como profesional independiente.\n\nEste contrato no crea una relación laboral, sociedad, mandato general ni representación entre las Partes.\n\nEl Docente sigue siendo responsable de sus declaraciones fiscales, cotizaciones, seguros, permisos y demás obligaciones de su actividad.\n\nEl Docente no puede comprometer jurídica o financieramente al Grupo ni a TutorSphere sin autorización previa por escrito."),
        new("art3", "Artículo 3 — Cualificaciones e información facilitada",
            "El Docente certifica que los datos y documentos transmitidos son exactos, completos y auténticos, en particular documentos de identidad, diplomas, referencias, autorizaciones para enseñar y verificaciones de antecedentes cuando se exijan.\n\nDebe informar de inmediato al Grupo de cualquier cambio que pueda afectar a su aptitud.\n\nToda declaración falsa o uso de documentos falsificados puede dar lugar a la suspensión inmediata de la cuenta y a la resolución del contrato."),
        new("art4", "Artículo 4 — Obligaciones del docente",
            "El Docente se compromete a: 1. prestar servicios profesionales, respetuosos y adaptados; 2. respetar horarios y compromisos aceptados; 3. preparar debidamente las clases; 4. mantener actualizada su disponibilidad en TutorSphere; 5. registrar asistencia, deberes, observaciones e informes; 6. respetar programas, objetivos y consignas del Grupo; 7. usar un lenguaje apropiado y un comportamiento ejemplar; 8. mantener un entorno de aprendizaje seguro; 9. preservar la confidencialidad de alumnos y familias; 10. respetar las reglas de TutorSphere; 11. comunicar con rapidez incidentes; 12. no delegar las clases sin autorización escrita."),
        new("art5", "Artículo 5 — Protección de la infancia",
            "El Docente reconoce que algunos servicios conciernen a menores y se compromete a respetar las normas de protección infantil y las leyes aplicables.\n\nQueda prohibido: adoptar un comportamiento violento, humillante, discriminatorio o intimidatorio; mantener intercambios sexuales, románticos o inapropiados con un alumno; solicitar imágenes, vídeos o datos personales sin justificación pedagógica; reunirse físicamente con un alumno sin autorización previa del padre o tutor; organizar comunicaciones privadas fuera de los canales autorizados; solicitar o aceptar regalos, pagos o ventajas no autorizados.\n\nToda situación que pueda comprometer la seguridad o el bienestar de un niño debe comunicarse de inmediato al Grupo."),
        new("art6", "Artículo 6 — Uso de TutorSphere",
            "El Docente debe utilizar su propia cuenta TutorSphere y proteger sus credenciales. Es responsable de las acciones realizadas desde su cuenta, salvo que demuestre que esta fue comprometida tras haber adoptado medidas de seguridad razonables.\n\nNo debe compartir la cuenta, eludir la seguridad, extraer o usar datos sin autorización, perturbar el servicio ni usar la plataforma con fines ilícitos o ajenos a la misión pedagógica.\n\nTutorSphere puede conservar datos técnicos y registros de actividad necesarios para la seguridad, el cumplimiento, la facturación y la resolución de controversias."),
        new("art7", "Artículo 7 — Organización de las clases",
            "Las clases pueden ser en línea o presenciales, según la oferta aceptada. Horarios, materias, niveles, duraciones y modalidades se definen en TutorSphere o en un anexo.\n\nEl Docente debe avisar al Grupo y a las personas concernidas en caso de indisponibilidad.\n\n**Plazo mínimo de anulación:** {{CANCELLATION_NOTICE}}\n**Tolerancia de retraso:** {{LATE_TOLERANCE}}\n**Consecuencia de una ausencia injustificada:** {{UNJUSTIFIED_ABSENCE_RULE}}"),
        new("art8", "Artículo 8 — Remuneración",
            "A cambio de los servicios efectivamente prestados y validados, el Docente percibe:\n\n**Tarifa o fórmula:** {{COMPENSATION_RATE}}\n**Divisa:** {{CURRENCY}}\n**Frecuencia de pago:** {{PAYMENT_FREQUENCY}}\n**Medio de pago:** {{PAYMENT_METHOD}}\n**Comisión o gastos:** {{APPLICABLE_FEES}}\n\nEl pago puede condicionarse a la validación de asistencias, informes y demás elementos exigidos. Impuestos, gastos bancarios y obligaciones fiscales personales corren a cargo del Docente, salvo disposición legal en contrario.\n\nToda reclamación de pago debe presentarse en un plazo de {{PAYMENT_DISPUTE_PERIOD}} días."),
        new("art9", "Artículo 9 — Relación con alumnos y padres",
            "El Docente debe usar los medios de comunicación autorizados por el Grupo.\n\nDurante el contrato y durante {{NON_SOLICITATION_PERIOD}} después de su cese, se compromete, en los límites permitidos por la ley, a no eludir la plataforma para ofrecer servicios de pago directamente a alumnos o familias presentados por el Grupo.\n\nEsta cláusula no se aplica a relaciones cuya existencia previa pueda demostrar el Docente."),
        new("art10", "Artículo 10 — Confidencialidad",
            "Se consideran confidenciales todas las informaciones no públicas relativas a alumnos y familias, docentes y miembros del Grupo, métodos pedagógicos, tarifas, datos financieros, sistemas técnicos y documentos internos y estrategias del Grupo.\n\nEl Docente no puede divulgarlas ni utilizarlas fuera de la ejecución de este contrato. Esta obligación permanece tras el fin del contrato."),
        new("art11", "Artículo 11 — Protección de datos personales",
            "El Docente se compromete a tratar únicamente los datos personales necesarios, a conservarlos de forma segura, a no copiarlos inútilmente, a no transmitirlos a un tercero no autorizado, a suprimirlos o restituirlos al final de la misión y a comunicar de inmediato cualquier pérdida, revelación o uso no autorizado.\n\nLos datos se tratarán conforme a las leyes de privacidad aplicables."),
        new("art12", "Artículo 12 — Grabación de clases y uso de la IA",
            "Una clase solo puede grabarse, transcribirse o analizarse mediante inteligencia artificial si el Grupo ha autorizado esa función y se han obtenido los consentimientos legalmente exigidos.\n\nEl Docente es informado antes de activar una grabación o un análisis automatizado. Grabaciones, resúmenes y transcripciones solo se usarán para fines autorizados: seguimiento pedagógico, control de calidad, seguridad, informe o mejora del servicio."),
        new("art13", "Artículo 13 — Propiedad intelectual",
            "El Docente conserva la propiedad de los contenidos pedagógicos creados antes de este contrato. Concede al Grupo una autorización no exclusiva para usar los contenidos que deposite en TutorSphere en la medida necesaria para prestar, seguir y archivar los servicios.\n\nLos contenidos creados específicamente y remunerados por el Grupo pertenecen a: {{INTELLECTUAL_PROPERTY_RULE}}.\n\nEl Docente garantiza que posee los derechos necesarios y que respeta los derechos de autor."),
        new("art14", "Artículo 14 — Evaluación y control de calidad",
            "El Grupo puede evaluar la calidad a partir de informes de clase, puntualidad, comentarios de padres y alumnos, resultados pedagógicos, incidentes y controles de conformidad autorizados.\n\nEl Docente puede consultar las evaluaciones que le conciernen y presentar observaciones. En caso de dificultad, el Grupo puede pedir formación, un plan de mejora o una suspensión."),
        new("art15", "Artículo 15 — Duración",
            "El presente contrato se celebra: {{CONTRACT_DURATION_TYPE}}.\n\nEntra en vigor en la fecha de su firma electrónica por las Partes.\n\nSi es de duración determinada, finaliza el {{CONTRACT_END_DATE}}, salvo renovación o resolución anticipada."),
        new("art16", "Artículo 16 — Suspensión y resolución",
            "Cada Parte puede resolver el contrato respetando un preaviso de {{TERMINATION_NOTICE}} días.\n\nEl Grupo puede suspender de inmediato al Docente en caso de riesgo para la seguridad de un alumno, fraude o declaración falsa, violación grave de la confidencialidad, comportamiento abusivo o discriminatorio, incumplimiento reiterado de horarios u obligaciones pedagógicas, uso no autorizado de datos, o incumplimiento grave de este contrato o de la ley.\n\nAntes de una resolución definitiva, el Docente debe normalmente ser informado de los motivos y poder presentar observaciones, salvo urgencia de seguridad u obligación legal."),
        new("art17", "Artículo 17 — Efectos del fin del contrato",
            "Al término del contrato, el Docente debe terminar o transmitir los informes pendientes, restituir o suprimir los datos confidenciales, dejar de usar los recursos y accesos del Grupo y respetar las obligaciones que permanecen.\n\nLos importes debidos por servicios válidamente prestados siguen siendo exigibles."),
        new("art18", "Artículo 18 — Responsabilidad",
            "Cada Parte es responsable de sus actos, errores, omisiones e infracciones de la ley. El Docente es responsable de la calidad profesional de sus servicios y de los daños derivados de una falta, negligencia grave o conducta intencionada.\n\nTutorSphere es una herramienta tecnológica de gestión y comunicación. La plataforma no sustituye la responsabilidad pedagógica del Grupo o del Docente.\n\nNinguna disposición limita una responsabilidad que no pueda excluirse legalmente."),
        new("art19", "Artículo 19 — Fuerza mayor",
            "Ninguna Parte es responsable de un retraso causado por un acontecimiento razonablemente independiente de su voluntad, en particular una catástrofe, una avería mayor, un conflicto, una decisión gubernamental o una interrupción generalizada de las comunicaciones.\n\nLa Parte afectada debe informar a la otra lo antes posible y adoptar medidas razonables para reducir las consecuencias."),
        new("art20", "Artículo 20 — Resolución de controversias",
            "Las Partes se comprometen primero a buscar una solución amistosa. Toda reclamación debe transmitirse por escrito con los hechos, elementos justificativos y la solución pedida.\n\nA falta de acuerdo en un plazo de {{AMICABLE_RESOLUTION_PERIOD}} días, la controversia se someterá a: {{DISPUTE_RESOLUTION_METHOD}}."),
        new("art21", "Artículo 21 — Derecho aplicable",
            "El presente contrato se rige por las leyes de: {{GOVERNING_JURISDICTION}}.\n\nLos tribunales u organismos competentes son los de: {{COMPETENT_COURT_LOCATION}}.\n\nEsta cláusula se aplica sin perjuicio de las normas imperativas del país de residencia del Docente o del lugar de ejecución de los servicios."),
        new("art22", "Artículo 22 — Modificación",
            "Toda modificación importante debe comunicarse al Docente. Cuando una nueva versión requiera su consentimiento, se le enviará un nuevo contrato o una adenda para su firma.\n\nLa nueva versión no sustituye a la anterior hasta su aceptación, salvo que la ley autorice otro procedimiento."),
        new("art23", "Artículo 23 — Integridad y divisibilidad",
            "Este contrato y sus anexos representan la integridad del acuerdo entre las Partes sobre su objeto.\n\nSi una disposición se declara inválida, las demás siguen aplicándose en la medida permitida por la ley."),
        new("art24", "Artículo 24 — Firma electrónica",
            "El Docente reconoce haber recibido el contrato en una lengua que comprende, haber podido consultar el documento íntegro, haber verificado la exactitud de sus datos, haber aceptado cada condición obligatoria, haber firmado libremente por vía electrónica y haber recibido o obtenido acceso a una copia firmada.\n\nTras la firma, el sistema genera un PDF definitivo con el número único, la versión y la lengua, la fecha y hora de la firma, la identidad de los firmantes, la huella digital, un código QR de verificación y las pruebas del registro de auditoría."),
        new("annexes", "Anexos",
            "Forman parte integrante de este contrato, tal como figuran en TutorSphere:\n\n• Anexo A — Materias y niveles impartidos\n• Anexo B — Disponibilidades y horarios\n• Anexo C — Remuneración y modalidades de pago\n• Anexo D — Política de anulación y ausencia\n• Anexo E — Código de conducta y protección de la infancia\n• Anexo F — Política de confidencialidad y protección de datos\n• Anexo G — Normas de uso de TutorSphere")
    ];

    private static IReadOnlyList<TeacherContractSectionDef> GermanSections() =>
    [
        new("parties", "Die Parteien",
            "### 1. Die Gruppe oder Einrichtung\n\n**Name:** {{GROUP_NAME}}\n**Rechtsform:** {{GROUP_LEGAL_FORM}}\n**Registernummer:** {{GROUP_REGISTRATION_NUMBER}}\n**Adresse:** {{GROUP_ADDRESS}}\n**Vertreten durch:** {{GROUP_ADMIN_NAME}}\n**Funktion:** {{GROUP_ADMIN_ROLE}}\n\nNachfolgend „die Gruppe“ genannt.\n\n### 2. Die Lehrkraft\n\n**Vor- und Nachname:** {{TEACHER_FULL_NAME}}\n**Geburtsdatum:** {{TEACHER_DATE_OF_BIRTH}}\n**Adresse:** {{TEACHER_ADDRESS}}\n**Wohnsitzland:** {{TEACHER_COUNTRY}}\n**E-Mail:** {{TEACHER_EMAIL}}\n**Telefon:** {{TEACHER_PHONE}}\n**Unterrichtete Fächer:** {{TEACHER_SUBJECTS}}\n**Schulstufen:** {{TEACHER_LEVELS}}\n\nNachfolgend „die Lehrkraft“ genannt.\n\nGruppe und Lehrkraft werden gemeinsam als „die Parteien“ bezeichnet."),
        new("preamble", "Präambel",
            "Die Gruppe nutzt die Plattform **TutorSphere**, um Nachhilfe, schulische Unterstützung und pädagogische Begleitung zu organisieren und zu erbringen.\n\nDie Lehrkraft erklärt, über die erforderlichen Kompetenzen, Qualifikationen und Erfahrungen zu verfügen.\n\nDie Parteien wollen mit diesem Vertrag die Bedingungen ihrer Zusammenarbeit festlegen."),
        new("art1", "Artikel 1 — Gegenstand",
            "Dieser Vertrag bestimmt die Bedingungen, unter denen die Lehrkraft Nachhilfe, schulische Unterstützung oder pädagogische Begleitung für bei der Gruppe auf TutorSphere eingeschriebene Schüler erbringt.\n\nDie Leistungen können umfassen: Vorbereitung und Durchführung von Einzel- oder Gruppenunterricht; Bedarfsermittlung; Erstellung von Unterrichtsmaterial; Erstellung, Korrektur und Nachverfolgung von Hausaufgaben; Fortschrittsberichte; Kommunikation mit Eltern oder Erziehungsberechtigten; Teilnahme an Gruppentreffen; sowie jede andere von den Parteien vereinbarte pädagogische Tätigkeit."),
        new("art2", "Artikel 2 — Status der Lehrkraft",
            "Soweit das anwendbare Recht nichts anderes vorschreibt, handelt die Lehrkraft als selbstständige Fachkraft.\n\nDieser Vertrag begründet kein Arbeitsverhältnis, keine Gesellschaft, kein allgemeines Mandat und keine Vertretung zwischen den Parteien.\n\nDie Lehrkraft bleibt für Steuererklärungen, Sozialbeiträge, Versicherungen, Genehmigungen und sonstige Pflichten ihrer Tätigkeit verantwortlich.\n\nDie Lehrkraft darf die Gruppe oder TutorSphere ohne vorherige schriftliche Ermächtigung nicht rechtlich oder finanziell verpflichten."),
        new("art3", "Artikel 3 — Qualifikationen und Angaben",
            "Die Lehrkraft bestätigt, dass die übermittelten Angaben und Unterlagen zutreffend, vollständig und echt sind, insbesondere Ausweise, Diplome, Referenzen, Lehrbefugnisse und erforderliche Hintergrundprüfungen.\n\nÄnderungen, die die Eignung beeinträchtigen können, sind der Gruppe unverzüglich mitzuteilen.\n\nFalschangaben oder gefälschte Unterlagen können zur sofortigen Kontosperrung und zur Kündigung führen."),
        new("art4", "Artikel 4 — Pflichten der Lehrkraft",
            "Die Lehrkraft verpflichtet sich: 1. professionelle, respektvolle und angepasste Leistungen zu erbringen; 2. akzeptierte Termine einzuhalten; 3. den Unterricht sorgfältig vorzubereiten; 4. die Verfügbarkeit in TutorSphere aktuell zu halten; 5. Anwesenheit, Hausaufgaben, Beobachtungen und Berichte zu erfassen; 6. Lehrpläne, Ziele und Vorgaben der Gruppe zu achten; 7. angemessene Sprache und vorbildliches Verhalten zu zeigen; 8. ein sicheres Lernumfeld zu wahren; 9. die Vertraulichkeit von Schülern und Familien zu schützen; 10. die Regeln von TutorSphere einzuhalten; 11. Vorfälle rasch zu melden; 12. Unterricht nicht ohne schriftliche Genehmigung zu delegieren."),
        new("art5", "Artikel 5 — Kinderschutz",
            "Die Lehrkraft erkennt an, dass einige Leistungen Minderjährige betreffen, und verpflichtet sich zur Einhaltung des Kinderschutzes und des geltenden Rechts.\n\nUntersagt sind insbesondere: gewalttätiges, demütigendes, diskriminierendes oder einschüchterndes Verhalten; sexuelle, romantische oder unangemessene Kontakte mit einem Schüler; das Anfordern von Bildern, Videos oder persönlichen Daten ohne pädagogische Rechtfertigung; ein persönliches Treffen ohne vorherige Zustimmung der Eltern oder Erziehungsberechtigten; private Kommunikation außerhalb zugelassener Kanäle; das Fordern oder Annehmen unzulässiger Geschenke, Zahlungen oder Vorteile.\n\nJede Situation, die die Sicherheit oder das Wohl eines Kindes gefährden kann, ist der Gruppe unverzüglich zu melden."),
        new("art6", "Artikel 6 — Nutzung von TutorSphere",
            "Die Lehrkraft muss ihr eigenes TutorSphere-Konto verwenden und Zugangsdaten schützen. Sie haftet für Handlungen über ihr Konto, sofern sie nicht nachweist, dass es nach angemessenen Sicherheitsmaßnahmen kompromittiert wurde.\n\nUntersagt sind das Teilen des Kontos, das Umgehen von Sicherheitsmaßnahmen, die unbefugte Nutzung von Daten, die Störung des Dienstes sowie eine rechtswidrige oder nicht pädagogische Nutzung.\n\nTutorSphere darf technische Daten und Aktivitätsprotokolle speichern, die für Sicherheit, Compliance, Abrechnung und Streitbeilegung erforderlich sind."),
        new("art7", "Artikel 7 — Organisation des Unterrichts",
            "Der Unterricht kann online oder in Präsenz stattfinden. Zeiten, Fächer, Stufen, Dauer und Modalitäten werden in TutorSphere oder in einer Anlage festgelegt.\n\nBei Verhinderung sind Gruppe und betroffene Personen zu informieren.\n\n**Mindestkündigungsfrist:** {{CANCELLATION_NOTICE}}\n**Verspätungstoleranz:** {{LATE_TOLERANCE}}\n**Folge einer unentschuldigten Abwesenheit:** {{UNJUSTIFIED_ABSENCE_RULE}}"),
        new("art8", "Artikel 8 — Vergütung",
            "Für tatsächlich erbrachte und validierte Leistungen erhält die Lehrkraft:\n\n**Satz oder Formel:** {{COMPENSATION_RATE}}\n**Währung:** {{CURRENCY}}\n**Zahlungshäufigkeit:** {{PAYMENT_FREQUENCY}}\n**Zahlungsmittel:** {{PAYMENT_METHOD}}\n**Gebühren:** {{APPLICABLE_FEES}}\n\nDie Zahlung kann von validierter Anwesenheit, Berichten und weiteren Nachweisen abhängen. Steuern, Bankgebühren und persönliche Steuerpflichten trägt die Lehrkraft, soweit das Gesetz nichts anderes vorsieht.\n\nZahlungsbeanstandungen sind innerhalb von {{PAYMENT_DISPUTE_PERIOD}} Tagen vorzubringen."),
        new("art9", "Artikel 9 — Beziehung zu Schülern und Eltern",
            "Die Lehrkraft nutzt die von der Gruppe zugelassenen Kommunikationswege.\n\nWährend der Vertragslaufzeit und {{NON_SOLICITATION_PERIOD}} danach verpflichtet sie sich im gesetzlich zulässigen Rahmen, die Plattform nicht zu umgehen, um den von der Gruppe vermittelten Schülern oder Familien direkt entgeltliche Leistungen anzubieten.\n\nDies gilt nicht für Beziehungen, deren Bestehen vor dem Beitritt nachgewiesen wird."),
        new("art10", "Artikel 10 — Vertraulichkeit",
            "Vertraulich sind alle nicht öffentlichen Informationen über Schüler und Familien, Lehrkräfte und Gruppenmitglieder, Lehrmethoden, Preise, Finanzdaten, technische Systeme sowie interne Unterlagen und Strategien der Gruppe.\n\nDie Lehrkraft darf sie außerhalb der Vertragserfüllung nicht offenlegen oder nutzen. Diese Pflicht gilt über das Vertragsende hinaus."),
        new("art11", "Artikel 11 — Schutz personenbezogener Daten",
            "Die Lehrkraft verarbeitet nur die für die Leistung erforderlichen personenbezogenen Daten, speichert sie sicher, kopiert sie nicht unnötig, übermittelt sie nicht an Unbefugte, löscht oder gibt sie am Ende des Auftrags zurück und meldet Verlust, Offenlegung oder unbefugte Nutzung unverzüglich.\n\nDie Verarbeitung erfolgt nach den geltenden Datenschutzgesetzen."),
        new("art12", "Artikel 12 — Aufzeichnung und KI",
            "Eine Stunde darf nur aufgezeichnet, transkribiert oder durch KI analysiert werden, wenn die Gruppe diese Funktion erlaubt hat und die gesetzlich erforderlichen Einwilligungen vorliegen.\n\nDie Lehrkraft wird vor Aktivierung einer Aufzeichnung oder automatisierten Analyse informiert. Aufzeichnungen, Zusammenfassungen und Transkripte dürfen nur für zulässige Zwecke verwendet werden."),
        new("art13", "Artikel 13 — Geistiges Eigentum",
            "Die Lehrkraft behält das Eigentum an vor Vertragsschluss erstellten Lehrinhalten. Sie räumt der Gruppe ein nicht ausschließliches Nutzungsrecht an auf TutorSphere hinterlegten Inhalten ein, soweit dies zur Erbringung, Nachverfolgung und Archivierung erforderlich ist.\n\nSpeziell für die Gruppe erstellte und vergütete Inhalte gehören: {{INTELLECTUAL_PROPERTY_RULE}}.\n\nDie Lehrkraft gewährleistet die erforderlichen Rechte und die Achtung des Urheberrechts."),
        new("art14", "Artikel 14 — Bewertung und Qualität",
            "Die Gruppe kann die Qualität anhand von Stundenberichten, Pünktlichkeit, Rückmeldungen, pädagogischen Ergebnissen, gemeldeten Vorfällen und zulässigen Kontrollen bewerten.\n\nDie Lehrkraft kann sie betreffende Bewertungen einsehen und Stellung nehmen. Bei Schwierigkeiten kann die Gruppe Schulung, einen Verbesserungsplan oder eine Aussetzung verlangen."),
        new("art15", "Artikel 15 — Laufzeit",
            "Dieser Vertrag wird geschlossen: {{CONTRACT_DURATION_TYPE}}.\n\nEr tritt mit der elektronischen Unterzeichnung durch die Parteien in Kraft.\n\nBei befristeter Laufzeit endet er am {{CONTRACT_END_DATE}}, sofern er nicht verlängert oder vorzeitig beendet wird."),
        new("art16", "Artikel 16 — Aussetzung und Kündigung",
            "Jede Partei kann mit einer Frist von {{TERMINATION_NOTICE}} Tagen kündigen.\n\nDie Gruppe kann die Lehrkraft sofort aussetzen bei Gefahr für die Sicherheit eines Schülers, Betrug oder Falschangabe, schwerwiegender Vertraulichkeitsverletzung, missbräuchlichem oder diskriminierendem Verhalten, wiederholter Pflichtverletzung, unbefugter Datennutzung oder schwerwiegendem Vertrags- oder Rechtsverstoß.\n\nVor einer endgültigen Kündigung ist die Lehrkraft in der Regel über die Gründe zu informieren und anzuhören, außer bei Sicherheitsnotfall oder gesetzlicher Pflicht."),
        new("art17", "Artikel 17 — Folgen der Beendigung",
            "Bei Vertragsende muss die Lehrkraft ausstehende Berichte abschließen oder übergeben, vertrauliche Daten zurückgeben oder löschen, Ressourcen und Zugänge der Gruppe nicht mehr nutzen und fortbestehende Pflichten einhalten.\n\nBeträge für gültig erbrachte Leistungen bleiben zahlbar."),
        new("art18", "Artikel 18 — Haftung",
            "Jede Partei haftet für eigene Handlungen, Fehler, Unterlassungen und Rechtsverstöße. Die Lehrkraft haftet für die fachliche Qualität und für Schäden aus Verschulden, grober Fahrlässigkeit oder vorsätzlichem Verhalten.\n\nTutorSphere ist ein technisches Verwaltungs- und Kommunikationswerkzeug und ersetzt nicht die pädagogische Verantwortung von Gruppe oder Lehrkraft.\n\nKeine Bestimmung beschränkt eine gesetzlich unabdingbare Haftung."),
        new("art19", "Artikel 19 — Höhere Gewalt",
            "Keine Partei haftet für eine Verzögerung durch ein Ereignis außerhalb ihres zumutbaren Einflusses, insbesondere Katastrophe, schwerwiegenden Ausfall, Konflikt, behördliche Entscheidung oder weitreichende Kommunikationsunterbrechung.\n\nDie betroffene Partei informiert die andere so bald wie möglich und trifft angemessene Maßnahmen zur Schadensminderung."),
        new("art20", "Artikel 20 — Streitbeilegung",
            "Die Parteien suchen zunächst eine einvernehmliche Lösung. Jede Forderung ist schriftlich mit Sachverhalt, Belegen und beantragter Lösung zu übermitteln.\n\nKommt binnen {{AMICABLE_RESOLUTION_PERIOD}} Tagen keine Einigung zustande, wird die Streitigkeit vorgelegt: {{DISPUTE_RESOLUTION_METHOD}}."),
        new("art21", "Artikel 21 — Anwendbares Recht",
            "Dieser Vertrag unterliegt den Gesetzen von: {{GOVERNING_JURISDICTION}}.\n\nZuständig sind die Gerichte oder Stellen von: {{COMPETENT_COURT_LOCATION}}.\n\nVorbehalten bleiben zwingende Vorschriften des Wohnsitzlandes der Lehrkraft oder des Erfüllungsortes."),
        new("art22", "Artikel 22 — Änderung",
            "Jede wesentliche Änderung ist der Lehrkraft mitzuteilen. Erfordert eine neue Fassung ihre Zustimmung, ist ein neuer Vertrag oder eine Ergänzung zur Unterschrift zu übersenden.\n\nDie neue Fassung ersetzt die vorherige erst nach Annahme, sofern das Gesetz kein anderes Verfahren zulässt."),
        new("art23", "Artikel 23 — Vollständigkeit und Teilnichtigkeit",
            "Dieser Vertrag und seine Anlagen stellen die gesamte Vereinbarung der Parteien über seinen Gegenstand dar.\n\nIst eine Bestimmung unwirksam, bleiben die übrigen soweit gesetzlich zulässig anwendbar."),
        new("art24", "Artikel 24 — Elektronische Signatur",
            "Die Lehrkraft bestätigt, den Vertrag in einer verständlichen Sprache erhalten, das gesamte Dokument einsehen, ihre Angaben geprüft, jede Pflichtbedingung akzeptiert, frei elektronisch unterzeichnet und Zugang zu einer unterzeichneten Kopie erhalten zu haben.\n\nNach der Unterzeichnung erzeugt das System ein endgültiges PDF mit Nummer, Fassung und Sprache, Datum und Uhrzeit, Identität der Unterzeichnenden, digitaler Prüfsumme, Prüf-QR-Code und Auditnachweisen."),
        new("annexes", "Anlagen",
            "Bestandteil dieses Vertrags sind, wie in TutorSphere ausgewiesen:\n\n• Anlage A — Fächer und Stufen\n• Anlage B — Verfügbarkeiten und Zeiten\n• Anlage C — Vergütung und Zahlungsmodalitäten\n• Anlage D — Stornierungs- und Abwesenheitsrichtlinie\n• Anlage E — Verhaltenskodex und Kinderschutz\n• Anlage F — Datenschutzrichtlinie\n• Anlage G — Nutzungsregeln von TutorSphere")
    ];

    private static IReadOnlyList<TeacherContractSectionDef> PortugueseSections() =>
    [
        new("parties", "As partes",
            "### 1. O grupo ou estabelecimento\n\n**Nome:** {{GROUP_NAME}}\n**Forma jurídica:** {{GROUP_LEGAL_FORM}}\n**Número de registo:** {{GROUP_REGISTRATION_NUMBER}}\n**Morada:** {{GROUP_ADDRESS}}\n**Representado por:** {{GROUP_ADMIN_NAME}}\n**Função:** {{GROUP_ADMIN_ROLE}}\n\nA seguir designado «o Grupo».\n\n### 2. O professor\n\n**Nome completo:** {{TEACHER_FULL_NAME}}\n**Data de nascimento:** {{TEACHER_DATE_OF_BIRTH}}\n**Morada:** {{TEACHER_ADDRESS}}\n**País de residência:** {{TEACHER_COUNTRY}}\n**Correio eletrónico:** {{TEACHER_EMAIL}}\n**Telefone:** {{TEACHER_PHONE}}\n**Disciplinas lecionadas:** {{TEACHER_SUBJECTS}}\n**Níveis escolares:** {{TEACHER_LEVELS}}\n\nA seguir designado «o Professor».\n\nO Grupo e o Professor são coletivamente designados «as Partes»."),
        new("preamble", "Preâmbulo",
            "O Grupo utiliza a plataforma **TutorSphere** para organizar e prestar serviços de apoio escolar, tutoria e acompanhamento pedagógico.\n\nO Professor declara possuir as competências, qualificações e experiência necessárias.\n\nAs Partes pretendem definir, pelo presente contrato, as condições da sua colaboração."),
        new("art1", "Artigo 1.º — Objeto",
            "O presente contrato define as condições em que o Professor presta serviços de tutoria, apoio escolar ou acompanhamento pedagógico aos alunos inscritos junto do Grupo no TutorSphere.\n\nOs serviços podem incluir: preparação e animação de aulas individuais ou coletivas; avaliação das necessidades pedagógicas; preparação de materiais; criação, correção e acompanhamento de trabalhos; relatórios de progresso; comunicação com encarregados de educação; participação em reuniões do Grupo; e qualquer outra atividade pedagógica acordada."),
        new("art2", "Artigo 2.º — Estatuto do professor",
            "Salvo disposição legal em contrário, o Professor atua como profissional independente.\n\nEste contrato não cria relação de emprego, sociedade, mandato geral nem representação entre as Partes.\n\nO Professor permanece responsável pelas suas declarações fiscais, contribuições, seguros, autorizações e demais obrigações da atividade.\n\nO Professor não pode vincular jurídica ou financeiramente o Grupo ou o TutorSphere sem autorização prévia por escrito."),
        new("art3", "Artigo 3.º — Qualificações e informações",
            "O Professor certifica que os dados e documentos transmitidos são exatos, completos e autênticos, incluindo documentos de identidade, diplomas, referências, autorizações para ensinar e verificações de antecedentes quando exigidas.\n\nDeve informar imediatamente o Grupo de qualquer alteração que possa afetar a sua aptidão.\n\nQualquer declaração falsa ou uso de documentos falsificados pode originar a suspensão imediata da conta e a resolução do contrato."),
        new("art4", "Artigo 4.º — Obrigações do professor",
            "O Professor compromete-se a: 1. prestar serviços profissionais, respeitosos e adaptados; 2. respeitar horários e compromissos aceites; 3. preparar devidamente as aulas; 4. manter a disponibilidade atualizada no TutorSphere; 5. registar presenças, trabalhos, observações e relatórios; 6. respeitar programas, objetivos e instruções do Grupo; 7. usar linguagem apropriada e comportamento exemplar; 8. manter um ambiente de aprendizagem seguro; 9. preservar a confidencialidade dos alunos e famílias; 10. respeitar as regras do TutorSphere; 11. comunicar rapidamente incidentes; 12. não delegar aulas sem autorização escrita."),
        new("art5", "Artigo 5.º — Proteção de crianças",
            "O Professor reconhece que alguns serviços dizem respeito a menores e compromete-se a respeitar as regras de proteção infantil e a lei aplicável.\n\nÉ proibido: adotar comportamento violento, humilhante, discriminatório ou intimidatório; ter intercâmbios sexuais, românticos ou inadequados com um aluno; pedir imagens, vídeos ou dados pessoais sem justificação pedagógica; encontrar-se fisicamente com um aluno sem autorização prévia do encarregado de educação; organizar comunicações privadas fora dos canais autorizados; solicitar ou aceitar prendas, pagamentos ou vantagens não autorizados.\n\nQualquer situação que possa comprometer a segurança ou o bem-estar de uma criança deve ser comunicada imediatamente ao Grupo."),
        new("art6", "Artigo 6.º — Utilização do TutorSphere",
            "O Professor deve usar a sua própria conta TutorSphere e proteger as credenciais. É responsável pelas ações realizadas a partir da conta, salvo se demonstrar que esta foi comprometida após medidas de segurança razoáveis.\n\nNão deve partilhar a conta, contornar a segurança, extrair ou usar dados sem autorização, perturbar o serviço nem usar a plataforma para fins ilícitos ou alheios à missão pedagógica.\n\nO TutorSphere pode conservar dados técnicos e registos de atividade necessários à segurança, conformidade, faturação e resolução de litígios."),
        new("art7", "Artigo 7.º — Organização das aulas",
            "As aulas podem ser em linha ou presenciais, segundo a oferta aceite. Horários, disciplinas, níveis, durações e modalidades são definidos no TutorSphere ou num anexo.\n\nO Professor deve avisar o Grupo e as pessoas visadas em caso de indisponibilidade.\n\n**Prazo mínimo de anulação:** {{CANCELLATION_NOTICE}}\n**Tolerância de atraso:** {{LATE_TOLERANCE}}\n**Consequência de uma ausência injustificada:** {{UNJUSTIFIED_ABSENCE_RULE}}"),
        new("art8", "Artigo 8.º — Remuneração",
            "Em contrapartida dos serviços efetivamente prestados e validados, o Professor recebe:\n\n**Taxa ou fórmula:** {{COMPENSATION_RATE}}\n**Moeda:** {{CURRENCY}}\n**Frequência de pagamento:** {{PAYMENT_FREQUENCY}}\n**Meio de pagamento:** {{PAYMENT_METHOD}}\n**Comissões ou encargos:** {{APPLICABLE_FEES}}\n\nO pagamento pode depender da validação de presenças, relatórios e outros elementos exigidos. Impostos, encargos bancários e obrigações fiscais pessoais cabem ao Professor, salvo disposição legal em contrário.\n\nQualquer contestação de pagamento deve ser apresentada no prazo de {{PAYMENT_DISPUTE_PERIOD}} dias."),
        new("art9", "Artigo 9.º — Relação com alunos e encarregados de educação",
            "O Professor deve usar os meios de comunicação autorizados pelo Grupo.\n\nDurante o contrato e durante {{NON_SOLICITATION_PERIOD}} após o seu termo, compromete-se, nos limites permitidos pela lei, a não contornar a plataforma para oferecer serviços pagos diretamente a alunos ou famílias apresentados pelo Grupo.\n\nEsta cláusula não se aplica a relações cuja existência anterior o Professor possa demonstrar."),
        new("art10", "Artigo 10.º — Confidencialidade",
            "São confidenciais todas as informações não públicas relativas a alunos e famílias, professores e membros do Grupo, métodos pedagógicos, tarifas, dados financeiros, sistemas técnicos e documentos internos e estratégias do Grupo.\n\nO Professor não pode divulgá-las nem utilizá-las fora da execução deste contrato. Esta obrigação subsiste após o termo do contrato."),
        new("art11", "Artigo 11.º — Proteção de dados pessoais",
            "O Professor compromete-se a tratar apenas os dados pessoais necessários, conservá-los de forma segura, não os copiar desnecessariamente, não os transmitir a terceiros não autorizados, eliminá-los ou restituí-los no fim da missão e comunicar imediatamente qualquer perda, divulgação ou utilização não autorizada.\n\nOs dados devem ser tratados em conformidade com as leis de privacidade aplicáveis."),
        new("art12", "Artigo 12.º — Gravação das aulas e utilização de IA",
            "Uma aula só pode ser gravada, transcrita ou analisada por inteligência artificial se o Grupo tiver autorizado essa funcionalidade e tiverem sido obtidos os consentimentos legalmente exigidos.\n\nO Professor é informado antes da ativação de uma gravação ou análise automatizada. Gravações, resumos e transcrições só podem ser usados para fins autorizados."),
        new("art13", "Artigo 13.º — Propriedade intelectual",
            "O Professor conserva a propriedade dos conteúdos pedagógicos criados antes deste contrato. Concede ao Grupo uma autorização não exclusiva para usar os conteúdos que colocar no TutorSphere na medida necessária à prestação, acompanhamento e arquivo dos serviços.\n\nOs conteúdos criados especificamente e remunerados pelo Grupo pertencem a: {{INTELLECTUAL_PROPERTY_RULE}}.\n\nO Professor garante que possui os direitos necessários e que respeita os direitos de autor."),
        new("art14", "Artigo 14.º — Avaliação e qualidade",
            "O Grupo pode avaliar a qualidade a partir de relatórios de aula, pontualidade, comentários de pais e alunos, resultados pedagógicos, incidentes e controlos de conformidade autorizados.\n\nO Professor pode consultar as avaliações que lhe dizem respeito e apresentar observações. Em caso de dificuldade, o Grupo pode pedir formação, um plano de melhoria ou uma suspensão."),
        new("art15", "Artigo 15.º — Duração",
            "O presente contrato é celebrado: {{CONTRACT_DURATION_TYPE}}.\n\nEntra em vigor na data da sua assinatura eletrónica pelas Partes.\n\nSe for a prazo certo, termina em {{CONTRACT_END_DATE}}, salvo renovação ou resolução antecipada."),
        new("art16", "Artigo 16.º — Suspensão e resolução",
            "Cada Parte pode resolver o contrato com um pré-aviso de {{TERMINATION_NOTICE}} dias.\n\nO Grupo pode suspender imediatamente o Professor em caso de risco para a segurança de um aluno, fraude ou declaração falsa, violação grave da confidencialidade, comportamento abusivo ou discriminatório, incumprimento reiterado de horários ou obrigações pedagógicas, utilização não autorizada de dados, ou incumprimento grave deste contrato ou da lei.\n\nAntes de uma resolução definitiva, o Professor deve normalmente ser informado dos motivos e poder apresentar observações, salvo urgência de segurança ou obrigação legal."),
        new("art17", "Artigo 17.º — Efeitos do termo do contrato",
            "No termo do contrato, o Professor deve concluir ou transmitir relatórios em falta, restituir ou eliminar dados confidenciais, cessar o uso dos recursos e acessos do Grupo e respeitar as obrigações que subsistam.\n\nOs montantes devidos por serviços validamente prestados permanecem exigíveis."),
        new("art18", "Artigo 18.º — Responsabilidade",
            "Cada Parte é responsável pelos seus atos, erros, omissões e violações da lei. O Professor é responsável pela qualidade profissional dos seus serviços e pelos danos resultantes de culpa, negligência grave ou conduta intencional.\n\nO TutorSphere é uma ferramenta tecnológica de gestão e comunicação. A plataforma não substitui a responsabilidade pedagógica do Grupo ou do Professor.\n\nNenhuma disposição limita uma responsabilidade que não possa ser legalmente excluída."),
        new("art19", "Artigo 19.º — Força maior",
            "Nenhuma Parte é responsável por um atraso causado por um evento razoavelmente independente da sua vontade, nomeadamente catástrofe, avaria grave, conflito, decisão governamental ou interrupção generalizada das comunicações.\n\nA Parte afetada deve informar a outra o mais rapidamente possível e tomar medidas razoáveis para reduzir as consequências."),
        new("art20", "Artigo 20.º — Resolução de litígios",
            "As Partes comprometem-se primeiro a procurar uma solução amigável. Qualquer reclamação deve ser enviada por escrito com os factos, elementos justificativos e a solução pedida.\n\nNa falta de acordo no prazo de {{AMICABLE_RESOLUTION_PERIOD}} dias, o litígio será submetido a: {{DISPUTE_RESOLUTION_METHOD}}."),
        new("art21", "Artigo 21.º — Direito aplicável",
            "O presente contrato rege-se pelas leis de: {{GOVERNING_JURISDICTION}}.\n\nOs tribunais ou organismos competentes são os de: {{COMPETENT_COURT_LOCATION}}.\n\nEsta cláusula aplica-se sem prejuízo das regras imperativas do país de residência do Professor ou do local de execução dos serviços."),
        new("art22", "Artigo 22.º — Modificação",
            "Qualquer alteração importante deve ser comunicada ao Professor. Quando uma nova versão exigir o seu consentimento, ser-lhe-á enviado um novo contrato ou um aditamento para assinatura.\n\nA nova versão só substitui a anterior após aceitação, salvo se a lei autorizar outro procedimento."),
        new("art23", "Artigo 23.º — Integralidade e divisibilidade",
            "Este contrato e os seus anexos representam a integralidade do acordo entre as Partes quanto ao seu objeto.\n\nSe uma disposição for declarada inválida, as restantes continuam a aplicar-se na medida permitida pela lei."),
        new("art24", "Artigo 24.º — Assinatura eletrónica",
            "O Professor reconhece ter recebido o contrato numa língua que compreende, ter podido consultar o documento na íntegra, ter verificado a exatidão dos seus dados, ter aceite cada condição obrigatória, ter assinado livremente por via eletrónica e ter recebido ou obtido acesso a uma cópia assinada.\n\nApós a assinatura, o sistema gera um PDF definitivo com o número único, a versão e a língua, a data e hora da assinatura, a identidade dos signatários, a impressão digital, um código QR de verificação e as provas do registo de auditoria."),
        new("annexes", "Anexos",
            "Fazem parte integrante deste contrato, tal como constam no TutorSphere:\n\n• Anexo A — Disciplinas e níveis lecionados\n• Anexo B — Disponibilidades e horários\n• Anexo C — Remuneração e modalidades de pagamento\n• Anexo D — Política de anulação e ausência\n• Anexo E — Código de conduta e proteção de crianças\n• Anexo F — Política de confidencialidade e proteção de dados\n• Anexo G — Regras de utilização do TutorSphere")
    ];
}
